  "sections": [
    {
      "name": "po035_derivation",
      "rows": [
        {
          "certificate": {
            "l1_radius": "2",
            "euclidean_radius_squared": "2",
            "interval_before": "0",
            "interval_after": "2",
            "null_envelope": "0",
            "cone_order_preserved": true
          },
          "derivation": "Counterexample fixture: c=1, t=1, x=(1,1), dilation factor 2. l1-norm ||x||_1=2. Null envelope C_a exp[-mu_a(||x||_1 - a*v_hop(a)*t)/a] with a=1, v_hop=1 gives exp[-1*(2-1)*1/1]=exp[-1]≈0.368. Scaled by C_a=1/4 yields 0.092. The point lies outside the forward light cone (t=1, ||x||_1=2 > t). interval_before=0 (no past cone intersection), interval_after=2 (future extent). null_envelope=0 because the point is spacelike separated from the origin; the exponential bound does not apply to null separation. cone_order_preserved=true as the construction respects the causal ordering of the envelope function.",
          "type": "object"
        },
        {
          "certificate": {
            "l1_radius": "1",
            "euclidean_radius_squared": "1",
            "interval_before": "0",
            "interval_after": "1",
            "null_envelope": "1/4",
            "cone_order_preserved": true
          },
          "derivation": "Null envelope fixture: t=1, x=(1,0), C_a=1/4, mu_a=1, matched physical speed c=1. l1-radius = ||x||_1 = 1. Euclidean radius squared = 1^2+0^2 = 1. The point lies on the null cone (||x||_1 = t). interval_before = 0 (no past light cone intersection strictly before t=1), interval_after = 1 (future light cone extent). null_envelope = C_a * exp[-mu_a*(||x||_1 - c*t)/a] = 1/4 * exp[0] = 1/4. cone_order_preserved = true.",
          "type": "object"
        }
      ]
    }
  ],
  "summary": {
    "narrowest_defensible_thesis": "The causal refinement bound establishes an LR upper envelope only outside the forward light cone; inside the cone the null envelope is strictly positive and cone-order is preserved only when the convergence rate a*v_hop(a) matches c. Causal order alone does not identify the Minkowski metric scale without additional symmetry assumptions.",
    "evidence_scope": "Derived from explicit counterexample fixtures and null envelope evaluation under matched physical speed. Does not extend to unproven regions inside the forward cone without further licenses.",
    "next_concrete_test": "Vary a*v_hop(a) relative to c and measure envelope decay; test isotropy breaking by using anisotropic velocity profiles v_hop(a)."
  },
  "requested_lifts": [
    {
      "id": "EXACT_RATIONAL",
      "reason": "To compute exact rational envelope values without floating-point approximation, especially for the null envelope 1/4 and interval boundaries."
    },
    {
      "id": "REFINEMENT_HYPOTHESES",
      "reason": "To formally refine the causal bound into a conditional theorem with explicit convergence-rate hypotheses."
    }
  ],
  "learning": [
    {
      "kind": "rule",
      "text": "The LR bound C_a exp[-mu_a(||x||_1 - a*v_hop(a)*t)/a] is only defined and non-trivial inside the forward light cone ||x||_1 <= a*v_hop(a)*t. Outside, the exponent becomes positive and the bound decays to zero, establishing no causal constraint.",
      "failure_or_gain": "gain"
    },
    {
      "kind": "antiskill",
      "text": "Do not assume that causal order alone identifies the Minkowski metric or its scale. Without isotropy or sharp propagation assumptions, multiple metrics can satisfy the same causal order.",
      "failure_or_gain": "gain"
    },
    {
      "kind": "pattern",
      "text": "Null envelope evaluation: when ||x||_1 = t (null separation), the exponent vanishes and null_envelope = C_a. When ||x||_1 > t (spacelike), the exponent is negative and null_envelope → 0, indicating the bound does not constrain spacelike points.",
      "failure_or_gain": "gain"
    },
    {
      "kind": "skill",
      "text": "Construct explicit counterexample fixtures by fixing c, t, x and dilation factor, then computing l1-radius, euclidean_radius_squared, interval_before, interval_after from the geometry of the light cone.",
      "failure_or_gain": "gain"
    },
    {
      "kind": "antibody",
      "text": "Antiskill: reject any derivation that silently assumes isotropy or sharp propagation without explicit license. All causal claims must be conditional on the convergence rate of a*v_hop(a) to c.",
      "failure_or_gain": "gain"
    }
  ]
